import pandas as pd
import numpy as np

def clean(df):
    df = df.copy()
    region_map = {'north': 'North', 'nort': 'North', 'south': 'South', 'suoth': 'South', 'east': 'East', 'west': 'West'}
    def norm_region(x):
        if pd.isna(x):
            return np.nan
        s = str(x).strip().lower()
        return region_map.get(s, s.title())
    df['Region'] = df['Region'].apply(norm_region)
    df['Price'] = pd.to_numeric(df['Price'].astype(str).str.replace(r'[$,]', '', regex=True), errors='coerce')
    df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce').astype('Int64')
    df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    d = clean(df)
    res = d[d['Category'] == 'Electronics'].groupby('Region')['Revenue'].sum()
    return {str(k): float(v) for k, v in res.items()}
